const input = $json.body ?? $json;
const fields = input.fields ?? input.event?.fields ?? {};
const clientIp = input.client_ip ?? fields.client_ip ?? input.src_ip ?? '10.0.0.99';
const reason = input.reason ?? '1분 내 로그인 5회 이상 실패';
const timestamp = input.timestamp ?? new Date().toISOString();

return [{
  json: {
    event_type: 'BRUTE_FORCE',
    client_ip: clientIp,
    detection_reason: reason,
    api_key_id: input.api_key_id ?? 'key-001',
    timestamp: timestamp
  }
}];

