={{ (() => {
  const detection = $('Normalize Brute Force Event').item.json;
  const response = $json;
  const blocked = response.ip_blocked === true || response.status === 'ok' || Boolean(response.incident);
  return '🚨 Brute Force 탐지\n'
    + '공격 IP: ' + String(detection.client_ip) + '\n'
    + '인시던트 ID: ' + String(response.incident_id || response.incident?.incident_id || 'INC-S2-BRUTEFORCE') + '\n'
    + '탐지 사유: ' + String(detection.detection_reason || '1분 내 로그인 5회 이상 실패') + '\n'
    + '대응 결과: IP 차단: ' + (blocked ? '완료' : '진행 중') + '\n'
    + 'EngineSquare · 시나리오 1';
})() }}

